components.css:
.ds-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; padding: 0 16px; border: 1px solid transparent; border-radius: 999px; font-family: var(--font-mono); font-size: 0.8125rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; cursor: pointer; transition: background-color 150ms var(--ease-out), border-color 150ms var(--ease-out), color 150ms var(--ease-out), transform 150ms var(--ease-out); }
.ds-btn-primary { background-color: var(--accent); color: var(--on-accent); }
.ds-btn-primary:hover { background-color: var(--accent-hover); }
.ds-btn-primary:active { transform: translateY(1px); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.ds-btn:disabled { cursor: not-allowed; opacity: 0.4; }

.ds-btn-outline { border-color: var(--ink-faint); color: var(--ink); background-color: transparent; }
.ds-btn-outline:hover { border-color: var(--ink-muted); background-color: var(--surface-hover); }
.ds-btn-outline:active { transform: translateY(1px); }
.ds-btn-outline:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

.ds-btn-icon { display: inline-flex; align-items: center; justify-content: center; width: 44px; height: 44px; flex-shrink: 0; padding: 0; border: none; border-radius: 999px; background-color: var(--surface-hover); color: var(--ink); cursor: pointer; transition: background-color 150ms var(--ease-out), transform 150ms var(--ease-out); }
.ds-btn-icon:hover:not(:disabled) { background-color: var(--surface-pressed); }
.ds-btn-icon:active:not(:disabled) { transform: translateY(1px); }
.ds-btn-icon:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.ds-chip-group { display: flex; align-items: center; gap: 4px; }
.ds-chip { min-height: 34px; padding: 0 8px; border: 1px solid transparent; border-radius: 999px; font-family: var(--font-mono); font-size: 0.6875rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); background-color: transparent; cursor: pointer; transition: background-color 150ms var(--ease-out), color 150ms var(--ease-out); }
.ds-chip:hover { background-color: var(--surface-hover); color: var(--ink); }
.ds-chip[aria-pressed='true'] { background-color: var(--accent); color: var(--on-accent); }
.ds-chip[aria-pressed='true']:hover { background-color: var(--accent-hover); color: var(--on-accent); }
.ds-chip:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.ds-field-block { margin: 0; }
.ds-field-label { display: block; font-family: var(--font-mono); font-size: 0.8125rem; line-height: 1.4; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink-faint); }
.ds-field { display: block; width: 100%; margin-top: 4px; padding: 10px 12px; border: 1px solid var(--rule); border-radius: 3px; background-color: var(--bg-raised); color: var(--ink); font-family: var(--font-body); font-size: 1.0625rem; transition: border-color 150ms var(--ease-out), box-shadow 150ms var(--ease-out); }
.ds-field::placeholder { color: var(--ink-faint); }
.ds-field:hover { border-color: var(--ink-faint); }
.ds-field:focus-visible { border-color: var(--accent); box-shadow: 0 0 0 3px var(--surface-pressed); outline: 2px solid var(--accent); outline-offset: 3px; }
.ds-field:user-invalid { border-color: var(--danger); }

.ds-nav-bar { background-color: var(--bg); position: sticky; top: 0; z-index: 40; border-bottom: 1px solid var(--rule); }
.ds-nav { width: var(--container); margin-inline: auto; display: flex; flex-wrap: wrap; align-items: center; column-gap: 24px; row-gap: 12px; padding-block: 16px; }
.ds-wordmark { margin: 0 auto 0 0; font-family: var(--font-mono); font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--ink); }
.ds-tag-accent { color: var(--accent); }
.ds-nav-list { display: flex; flex-wrap: wrap; gap: 20px 8px; margin: 0; padding: 0; list-style: none; }
.ds-nav-link { display: inline-block; padding-block: 4px; font-family: var(--font-mono); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); text-decoration: none; transition: color 150ms var(--ease-out); }
.ds-nav-link:hover { color: var(--accent); }
.ds-nav-link:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

.ds-row { border-block-end: 1px solid var(--rule); }
.ds-row-summary { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 16px; margin-inline: -8px; padding: 8px; border-radius: 6px; cursor: pointer; list-style: none; transition: background-color 150ms var(--ease-out); }
.ds-row-summary::-webkit-details-marker { display: none; }
.ds-row-summary:hover { background-color: var(--surface-hover); }
.ds-row-eyebrow { font-family: var(--font-mono); font-size: 0.8125rem; line-height: 1.4; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink-faint); font-variant-numeric: tabular-nums; }
.ds-row-title { margin: 0; flex: 1 1 auto; font-family: var(--font-display); font-weight: 600; font-size: clamp(1.25rem, 2.2vw, 1.625rem); line-height: 1.2; color: var(--ink); transition: color 150ms var(--ease-out); }
.ds-row-summary:hover .ds-row-title, .ds-row[open] .ds-row-title { color: var(--accent); }
.ds-row-marker { font-family: var(--font-mono); color: var(--ink-faint); transition: transform 280ms var(--ease-out), color 150ms var(--ease-out); }
.ds-row[open] .ds-row-marker { transform: rotate(45deg); color: var(--accent); }
.ds-row-body { margin-top: 16px; margin-inline-start: 8px; border-inline-start: 2px solid var(--accent); padding-inline-start: 16px; animation: ds-row-reveal 280ms var(--ease-out); }
.ds-row-prose { max-width: 68ch; margin: 0; line-height: 1.65; color: var(--ink-muted); }
@keyframes ds-row-reveal { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }
@media (prefers-reduced-motion: reduce) { .ds-row-summary, .ds-row-title, .ds-row-marker { transition-duration: 0.01ms; } .ds-row-body { animation-duration: 0.01ms; } }

.ds-rail { display: flex; gap: 8px; flex: 1 1 auto; min-width: 0; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; padding-block: 4px; margin: 0; list-style: none; }
.ds-rail::-webkit-scrollbar { display: none; }
.ds-rail > li { flex: 0 0 auto; scroll-snap-align: center; }
.ds-thumb { display: block; overflow: hidden; border: 2px solid var(--rule); border-radius: 6px; opacity: 0.55; padding: 0; background: none; cursor: pointer; transition: opacity 150ms var(--ease-out), border-color 150ms var(--ease-out); }
.ds-thumb img { display: block; width: 160px; height: auto; }
.ds-thumb:hover { opacity: 0.85; border-color: var(--ink-faint); }
.ds-thumb[data-active='true'] { opacity: 1; border-color: var(--accent); }
.ds-thumb:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }

.ds-section { width: var(--container); margin-inline: auto; padding-block: var(--section-pad-block); }
.ds-section-head > * + * { margin-block-start: 16px; }
.ds-section-head > .ds-eyebrow + * { margin-block-start: 4px; }
.ds-eyebrow { margin: 0; font-family: var(--font-mono); font-size: 0.8125rem; line-height: 1.4; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink-faint); }
.ds-section-title { margin: 0; font-family: var(--font-display); font-weight: 700; font-size: clamp(1.75rem, 4vw, 3rem); line-height: 1.1; text-transform: uppercase; color: var(--accent); }
.ds-lead { margin: 0; font-size: 1.125rem; line-height: 1.6; color: var(--ink-muted); }
.ds-section-body { margin-block-start: var(--space-stack); }
.ds-prose { max-width: 68ch; margin: 0; line-height: 1.65; color: var(--ink); }
